def resolve(path, cwd, links):
    """
    Resolve a path to its canonical absolute form, following symlinks.

    Args:
        path: Path to resolve (absolute or relative to cwd)
        cwd: Current working directory (canonical absolute path)
        links: Dict mapping canonical absolute paths to symlink targets

    Returns:
        Canonical absolute path, or None on error
    """
    if path is None or cwd is None or links is None:
        return None

    # Start with absolute path
    if path.startswith('/'):
        current = ''
    else:
        current = cwd

    # Split path into components
    components = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            # Move to parent directory
            if current == '':
                current = ''
            elif current == '/':
                current = '/'
            else:
                # Remove last component
                last_slash = current.rfind('/')
                if last_slash == 0:
                    current = '/'
                else:
                    current = current[:last_slash]
            i += 1
            continue

        # Append component to current path
        if current == '':
            candidate = '/' + component
        elif current == '/':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if this is a symlink
        if candidate in links:
            link_count += 1
            if link_count > max_links:
                return None

            # Get the symlink target
            target = links[candidate]

            # Resolve remaining components from the link target
            # First, resolve the link target relative to its containing directory
            if target.startswith('/'):
                # Absolute target
                target_path = target
            else:
                # Relative target - relative to directory containing the link
                if current == '':
                    link_dir = ''
                elif current == '/':
                    link_dir = '/'
                else:
                    last_slash = candidate.rfind('/')
                    link_dir = candidate[:last_slash]
                    if link_dir == '':
                        link_dir = '/'

                if link_dir == '/':
                    target_path = '/' + target
                else:
                    target_path = link_dir + '/' + target

            # Remaining components to process
            remaining = components[i+1:]

            # Recursively resolve target + remaining components
            return resolve(target_path, cwd, links) if not remaining else resolve(target_path + '/' + '/'.join(remaining), cwd, links)

        current = candidate
        i += 1

    # Clean up result
    if current == '':
        return '/'
    elif current == '/':
        return '/'
    else:
        # Remove trailing slashes (except for root)
        while current.endswith('/') and current != '/':
            current = current[:-1]
        return current

